package com.voicetxt.reader;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;

/** Real session, window lifecycle and pointer gestures; never touches user models/books. */
public final class PlaybackBubbleTest extends VoiceWarmupTest {
    final AtomicReference<Activity> resumed=new AtomicReference<>();
    final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){resumed.set(a);}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    void drag(PlaybackBubble.Bubble bubble,float dx,float dy){long time=SystemClock.uptimeMillis();float x=bubble.getX()+bubble.size/2f,y=bubble.getY()+bubble.size/2f;for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(time,time+16*action,action,x+(action==0?0:dx),y+(action==0?0:dy),0);bubble.onTouchEvent(event);event.recycle();}}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();Application app=(Application)context.getApplicationContext();SharedPreferences prefs=context.getSharedPreferences("reading_settings",0),bubblePrefs=context.getSharedPreferences("playback_bubble",0);Map<String,?> saved=new HashMap<>(prefs.getAll()),savedBubble=new HashMap<>(bubblePrefs.getAll());MainActivity reader=null;ModelManagerActivity manager=null;OfflineVoicesActivity voices=null;boolean success=false;
        try{app.registerActivityLifecycleCallbacks(callbacks);prefs.edit().putString("readingLanguage","").commit();reader=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","bubble_qa").putExtra("book_name","悬浮阅读入口验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=reader;await(()->a.system!=null&&a.system.initialized,"System voices not ready",30000);SystemSpeaker.Option selected=null;for(SystemSpeaker.Option option:a.system.options)if(SystemSpeaker.offlineUsable(option.voice)&&VoiceLanguages.matches("zh",option.voice.getLocale())){selected=option;break;}check(selected!=null,"Chinese voice missing");final String key=selected.key;StringBuilder text=new StringBuilder("第一章 悬浮阅读\n");for(int i=0;i<200;i++)text.append("我们沿着河边的小路慢慢前行，欣赏四周美丽的风景。\n");ui(()->{a.stop();a.originalVoiceLanguage="zh";a.systemVoiceKey=key;a.persistVoiceChoice(key,"zh");a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.position=0;a.rate=1.8f;a.showPosition(true);a.startReading();});await(()->a.playing&&a.latestHighlightEnd>0,"Speech did not start",20000);check(PlaybackBubble.instance.view==null,"Bubble covers reader");ui(a::onBackPressed);await(()->resumed.get() instanceof ShelfActivity&&PlaybackBubble.instance.view!=null,"Bubble missing on shelf",10000);final ShelfActivity shelf=(ShelfActivity)resumed.get();final PlaybackBubble controller=PlaybackBubble.instance;final int at=a.position;await(()->a.position>at,"Narration stopped behind shelf",15000);ui(()->{check(controller.view.playing,"Playing indicator incorrect");check(controller.view.isClickable()&&controller.view.getContentDescription().toString().contains(a.book),"Reader entry inaccessible");float x=controller.view.getX(),y=controller.view.getY();drag(controller.view,-shelf.getWindow().getDecorView().getWidth()*.45f,-200);check(resumed.get()==shelf&&a.playing,"Dragging opened/paused playback");check(Math.abs(controller.view.getX()-x)>20||Math.abs(controller.view.getY()-y)>20,"Drag did not move bubble");drag(controller.view,-10000,-10000);controller.view.bounds();check(controller.view.getX()>=controller.view.safe.left&&controller.view.getY()>=controller.view.safe.top,"Bubble escaped safe top/left");drag(controller.view,10000,10000);check(controller.view.getX()<=controller.view.safe.right&&controller.view.getY()<=controller.view.safe.bottom,"Bubble escaped safe bottom/right");drag(controller.view,-180,-240);});final float storedX=controller.relativeX,storedY=controller.relativeY;
            manager=(ModelManagerActivity)startActivitySync(new Intent(context,ModelManagerActivity.class).putExtra("home",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ModelManagerActivity m=manager;await(()->controller.activity==m&&controller.view!=null,"Bubble missing on My page",10000);ui(()->{check(Math.abs(controller.relativeX-storedX)<.001&&Math.abs(controller.relativeY-storedY)<.001,"Bubble position lost across pages");m.home=false;m.render();check(controller.view.getParent()==m.getWindow().getDecorView(),"Page rebuild removed bubble");});voices=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity v=voices;await(()->controller.activity==v&&controller.view!=null,"Bubble missing on voice manager",10000);ui(()->{a.stop(false);PlaybackService.active.parkPaused();check(controller.view!=null&&!controller.view.playing,"Paused state not reflected");controller.view.performClick();});await(()->resumed.get()==a&&controller.view==null,"Tap did not return to original reader",10000);check(!a.playing,"Bubble click unexpectedly resumed playback");ui(()->{a.startReading();a.onBackPressed();});await(()->resumed.get() instanceof ShelfActivity&&controller.view!=null,"Bubble did not return on shelf",10000);ui(()->((Activity)resumed.get()).moveTaskToBack(true));await(()->controller.activity==null&&controller.view==null,"Bubble remained outside app",10000);ui(()->context.startActivity(new Intent(context,ShelfActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));await(()->controller.view!=null&&controller.activity instanceof ShelfActivity,"Bubble not restored after foreground",10000);ui(()->{a.stop();check(controller.view==null,"Stopped session left stale bubble");});check((context.getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0,"Unexpected test build");result.putString("result","PASS: circular entry visible on shelf/My/translation/voice pages; drag and edge clamping; normalized position retained across pages; page rebuild preserves overlay; playing/paused indicators; click returns to same reader without changing playback; hidden on reader and outside app; removed when session stops");success=true;
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}
        finally{if(voices!=null){final Activity a=voices;ui(a::finish);}if(manager!=null){final Activity a=manager;ui(a::finish);}if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}app.unregisterActivityLifecycleCallbacks(callbacks);waitForIdleSync();restore(prefs,saved);restore(bubblePrefs,savedBubble);if(PlaybackBubble.instance!=null){PlaybackBubble.instance.relativeX=bubblePrefs.getFloat("x",1);PlaybackBubble.instance.relativeY=bubblePrefs.getFloat("y",.76f);}context.getSharedPreferences("reader_bubble_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_bubble_qa.txt.position").delete();}
        finish(success?-1:0,result);
    }
}
